	["desc.Bossmaster"] = "Una donna forte con lunghi capelli arancioni e un top verde acqua, appoggiata a un martello.",
	["desc.Janitor"] = "Un vecchio con la barba bianca e un cappotto verde, che regge una lanterna e un mocio accanto a un secchio.",
	["desc.Diamonddealer"] = "Una volpe con un cappotto viola, che mostra un diamante scintillante.",
	["desc.Trainer"] = "Un libro aperto su un piedistallo di pietra: il Manoscritto.",
	["desc.Transmogrifier"] = "Una scienziata con i capelli scuri e gli occhiali protettivi, che regge pozioni luminose.",
	["desc.Pawnbroker"] = "Un goblin verde appollaiato su un'altissima montagna di armi, scudi e tesori.",
	["desc.Conjurer"] = "Uno spirito blu e spettrale che fluttua sopra uno scrigno del tesoro.",
	["scene.title.necrodancer"] = "Immagine del titolo: Cadence, con la torcia alzata e il pugnale sguainato, affronta un fantasma azzurro pallido con una freccia che gli trapassa la testa, in un cimitero buio. Sopra di loro, il logo del gioco tra due teschi.",
	["scene.title.amplified"] = "Immagine del titolo di Amplified: Notturna, spada in pugno, combatte contro un mago scheletro con un cappello viola, il cui bastone crepita di fulmini.",
	["scene.title.synchrony"] = "Immagine del titolo di Synchrony: Klarinetta con la sua spada lunga, Cantastorie, il fantasma rattoppato con la lanterna verde, e Suzu con la sua arma inastata, sotto il logo di Synchrony.",
	["scene.title.halloween"] = "Immagine del titolo di Halloween, Dolcetto o scherzetto: Cantastorie, il fantasma rattoppato con la lanterna verde, e Cadence con una zucca intagliata in testa, tra zucche luminose.",
	["scene.title.christmas"] = "Immagine del titolo di Natale, Merry Cryptmas: Cadence con un cappotto rosso da Babbo Natale e la sua vanga; dietro di lei un enorme non morto dalla barba bianca con un cappello da Babbo Natale, fantasmi e una mietitrice incappucciata riempiono il cielo innevato.",
	["scene.zone1"] = "La cripta: pavimenti di terra scura e battuta, e muri di terra pieni di radici, ossa e teschi, alcuni di blocchi di pietra. Finché il tuo moltiplicatore di monete è attivo, il pavimento lampeggia a scacchiera a ogni battito.",
	["scene.zone2"] = "Pavimenti di pietra muschiosa verde e verde acqua, muri di terra ricoperti di foglie e piccoli funghi arancioni, e muri di ciottoli chiari.",
	["scene.zone3"] = "Questa profondità è divisa in due: un lato caldo di roccia rossastra con pavimenti arancioni incandescenti, e un lato freddo di roccia grigio azzurra con pavimenti di ghiaccio blu.",
	["scene.zone4"] = "Le catacombe: pavimenti blu scuro e muri di mattoni viola ornati di scheletri, teschi e stendardi.",
	["scene.zone5"] = "Un laboratorio: pavimenti viola scuro con piastrelle oro e ciano, e muri di mattoni magenta coperti di tubi, cavi e macchinari.",
	["scene.boss"] = "Un'arena del boss: un pavimento di pietra scura, e muri di pietra chiara incastonati di teschi e ossa.",
	["scene.boss.NECRODANCER"] = "Il palco del NecroDancer: una pista da ballo verde fiancheggiata da giganteschi altoparlanti viola.",
	["cs.intro.1"] = "Notte in un cimitero. Cadence, una giovane donna con i capelli biondi, una bandana blu e una tunica rossa, si arrampica tra le lapidi con una torcia e una vanga, poi comincia a scavare.",
	["cs.intro.2"] = "La sua vanga sfonda il terreno e intorno a lei esplode un fumo viola.",
	["cs.intro.3"] = "Il terreno cede. Precipita nell'oscurità tra mani scheletriche che cercano di afferrarla.",
	["cs.intro.4"] = "Si schianta sul pavimento di pietra di una cripta, tra le ossa, e giace immobile in una pozza di sangue.",
	["cs.intro.5"] = "Una luce viola inonda la stanza. Uno stregone non morto dalla pelle blu, con una lunga barba bianca e un mantello rosso, incombe su di lei: il NecroDancer.",
	["cs.intro.6"] = "Con la sua magia le strappa il cuore dal petto e lo solleva, ghignando, mentre brilla.",
	["cs.intro.7"] = "Cadence si risveglia sul pavimento e si rialza con la sua vanga, mentre un fumo viola le esce dal petto.",
	["cs.intro.8"] = "Guarda avanti, decisa.",
	["cs.cadence1.1"] = "Una casa di legno illuminata da una candela. La piccola Cadence sbircia da dietro una porta.",
	["cs.cadence1.2"] = "Suo padre Dorian, con un berretto verde, mette una mappa e degli attrezzi in un baule.",
	["cs.cadence1.3"] = "La piccola Cadence abbassa lo sguardo, triste, accanto a suo zio Eli, un omone con la barba rossa e un cappello nero.",
	["cs.cadence1.4"] = "Anni dopo, Cadence adolescente fruga nel vecchio baule di suo padre, con una vanga appoggiata accanto.",
	["cs.cadence1.5"] = "Tira fuori i suoi appunti e una mappa, sorridendo.",
	["cs.cadence1.6"] = "Lo zio Eli la osserva dalla porta, accigliato, mentre Cadence distoglie lo sguardo.",
	["cs.cadence1.7"] = "Cadence stringe forte la mappa, decisa.",
	["cs.cadence2.1"] = "Un funerale su una collina verde. Persone in lutto vestite di scuro stanno accanto a una bara rossa coperta di fiori. La piccola Cadence canta accanto alla bara.",
	["cs.cadence2.2"] = "Dietro di lei, lo zio Eli punta un dito accusatore contro suo padre Dorian.",
	["cs.cadence2.3"] = "Vista dall'alto: Dorian allarga le mani, implorante, mentre Eli incombe su di lui.",
	["cs.cadence2.4"] = "Primo piano: Dorian distoglie lo sguardo, teso; Eli stringe il pugno.",
	["cs.cadence2.5"] = "Cadence volta loro le spalle e posa la mano sulla bara mentre petali rossi volano nel vento.",
	["cs.cadence3.1"] = "Un picnic al sole in riva a un lago. Una donna con un foulard rosso, Melody, suona un liuto mentre Dorian fa girare in tondo la piccola Cadence. Un cavallo pascola lì vicino.",
	["cs.cadence3.2"] = "La piccola Cadence balla e ride; dietro di lei i suoi genitori si abbracciano.",
	["cs.cadence3.3"] = "Più tardi, Melody giace malata a letto, con la testa fasciata e macchie scure sul braccio. Dorian le tiene la mano.",
	["cs.cadence3.4"] = "Dorian si volta, turbato, mentre la piccola Cadence osserva dalla porta.",
	["cs.cadence4.1"] = "Cadence è inginocchiata accanto a un uomo pallido con lunghi capelli rossi e un'armatura d'oro: suo padre, Dorian.",
	["cs.cadence4.2"] = "In una sala della cripta dagli archi viola, il NecroDancer allarga le braccia, con un liuto d'oro in una mano.",
	["cs.cadence4.3"] = "Una fiamma nell'altra mano si trasforma nel cuore pulsante di Cadence, e lui lo solleva per provocarla.",
	["cs.cadence4.4"] = "Cadence, con la vanga e il pugnale, sta fianco a fianco con Dorian, che impugna un pesante martello d'oro.",
	["cs.cadence5.1"] = "Il NecroDancer giace sconfitto sul pavimento. Dorian, nella sua armatura d'oro, tiene il liuto d'oro; dietro di lui Cadence risplende di luce viola.",
	["cs.cadence5.2"] = "Cadence, vanga in mano, guarda suo padre che si allontana con il liuto.",
	["cs.cadence5.3"] = "Fuori, sotto una luna verde, Cadence e Dorian escono tra lapidi e radici contorte, Dorian con il liuto in mano.",
	["cs.melody0.1"] = "Notte nel cimitero sotto una luna verde. Dorian suona il liuto d'oro sopra una bara aperta mentre Cadence è inginocchiata accanto. Nella bara giace una donna con i capelli rossi: Melody.",
	["cs.melody0.2"] = "Gli occhi di Melody si spalancano in un lampo di luce viola.",
	["cs.melody0.3"] = "Si mette a sedere nella bara, e Cadence e Dorian sorridono.",
	["cs.melody0.4"] = "Una visione del NecroDancer sconfitto, da cui esce un fumo viola.",
	["cs.melody0.5"] = "A casa, Melody, con una bandana rossa e un vestito verde, prende una vanga e il liuto d'oro.",
	["cs.melody0.6"] = "Tenendo alta una torcia, scende in un pozzo di pietra verso la cripta mentre tentacoli verdi sbucano dalle pareti.",
	["cs.melody1.1"] = "Nella stanza della malata, Melody giace a letto, pallida, con una rosa rossa sulla coperta. Dorian, con il suo berretto verde, è seduto accanto a lei e le tiene la mano.",
	["cs.melody1.2"] = "Primo piano: Dorian si china su di lei, con gli occhi socchiusi e duri, mentre lei giace debole con la testa fasciata.",
	["cs.melody2.1"] = "Nella cucina di una casetta di campagna, una donna dai capelli grigi con un liuto d'oro, Aria, solleva dolcemente il mento della giovane Melody.",
	["cs.melody2.2"] = "Più tardi, la sagoma scura di Aria esce dalla porta, mentre Melody le volta le spalle a testa bassa.",
	["cs.melody3.1"] = "Un villaggio al tramonto. Aria suona il suo liuto d'oro accanto al letto di un malato mentre la giovane Melody lo accudisce.",
	["cs.melody3.2"] = "Un abitante del villaggio con una torcia grida e indica Aria sulla soglia di una porta; altri si radunano con forconi e falci.",
	["cs.melody3.3"] = "Melody e Aria stanno insieme con il liuto, circondate dai forconi della folla, in un'esplosione di luce viola.",
	["cs.melody4.1"] = "Nella sala della cripta, Melody suona il liuto d'oro sopra il NecroDancer, che giace sul pavimento nel suo mantello rosso.",
	["cs.melody4.2"] = "Lui si rialza lentamente: pelle blu, occhi rossi, mani artigliate protese.",
	["cs.melody4.3"] = "Vista dall'alto: Melody continua a suonare mentre il NecroDancer striscia verso di lei.",
	["cs.melody4.4"] = "Primo piano del volto ringhiante del NecroDancer, con gli occhi rossi luminosi.",
	["cs.melody4.5"] = "Primo piano: Melody pizzica il liuto con calma e non si ferma mai.",
	["cs.melody4.6"] = "Il NecroDancer si erge e urla di rabbia in un'esplosione di luce viola.",
	["cs.melody5.1"] = "Il NecroDancer arretra barcollando verso una bara di pietra aperta.",
	["cs.melody5.2"] = "Un lampo di luce viola: una donna dai capelli grigi con un vestito viola lo trafigge alle spalle con un pugnale, mentre Melody guarda.",
	["cs.melody5.3"] = "Il suo mantello rosso si affloscia a terra ai piedi della donna.",
	["cs.melody5.4"] = "Nella cripta in penombra, Melody si volta verso la donna dai capelli grigi, che tiene ancora in mano il pugnale.",
	["cs.nocturna1.1"] = "Una cripta piena di strane macchine. Notturna, una vampira dalla pelle azzurro pallido, capelli rossi e ali di pipistrello, solleva una torcia accanto a un teschio gigante.",
	["cs.nocturna1.2"] = "Uno scheletro giace accasciato contro tubi e manometri, mentre una scintilla corre lungo un cavo.",
	["cs.nocturna1.3"] = "Vista dal basso: Notturna si erge con la torcia, le ali spiegate.",
	["cs.nocturna1.4"] = "Vola giù per una scala buia, con la torcia davanti a sé.",
	["cs.nocturna2.1"] = "Notturna solleva una torcia in una stanza piena di macchine e quadranti luminosi, allungando la mano verso il muro.",
	["cs.nocturna2.2"] = "Percorre un lungo corridoio di metallo fiancheggiato da cavi e luci.",
	["cs.nocturna2.3"] = "Primo piano: la sua mano blu tocca grossi cavi che crepitano di elettricità gialla.",
	["cs.nocturna2.4"] = "Vista dall'alto: segue i cavi luminosi sul pavimento.",
	["cs.nocturna2.5"] = "Continua a volare, ali spiegate, lungo un tunnel illuminato dal fuoco.",
	["cs.nocturna3.1"] = "Uno scheletro con un elmo, collegato alle macchine, siede accasciato tra scintille gialle.",
	["cs.nocturna3.2"] = "Primo piano: Notturna lo osserva, per nulla colpita.",
	["cs.nocturna3.3"] = "Si accovaccia accanto allo scheletro e tira i cavi infilati nella sua schiena.",
	["cs.nocturna3.4"] = "Stringe il fascio di cavi con entrambe le mani, poi serra i pugni.",
	["cs.nocturna3.5"] = "Si allontana da sola per un lungo corridoio; un altro scheletro collegato ai cavi pende dal muro.",
	["cs.nocturna4.1"] = "Un ricordo: una giovane donna dalla pelle bruna e dai capelli castani ricci urla e protende la mano mentre un vampiro blu dagli occhi rossi le morde il collo, con una chiesa alle loro spalle sotto un cielo viola.",
	["cs.nocturna4.2"] = "La sua pelle diventa azzurro pallido e i suoi capelli rossi, mentre alle sue spalle divampa il fuoco.",
	["cs.nocturna4.3"] = "In una foresta di betulle bianche, Notturna, ormai alata, si china su un animale abbattuto mentre occhi rossi la osservano dal buio.",
	["cs.nocturna4.4"] = "Un vampiro alto dai lunghi capelli rossi fluenti striscia fuori dall'oscurità verso di lei.",
	["cs.nocturna4.5"] = "Primo piano: Notturna si guarda le mani insanguinate, poi le stringe a pugno.",
	["cs.nocturna5.1"] = "Un laboratorio pieno di macchine. Un enorme corpo meccanico viola giace su un tavolo, con il petto che brilla mentre volano scintille.",
	["cs.nocturna5.2"] = "Notturna, spada in pugno, avanza verso di esso.",
	["cs.nocturna5.3"] = "Una donna con un cappotto viola e occhiali di ottone, arruffati capelli biondi e labbra blu, si volta dal suo lavoro: la Conduttrice.",
	["cs.nocturna5.4"] = "Notturna le punta contro la spada attraverso il vapore.",
	["cs.nocturna5.5"] = "La Conduttrice incrocia le braccia, per nulla colpita.",
	["cs.nocturna5.6"] = "Guarda Notturna dall'alto in basso con un sorriso furbo.",
	["cs.nocturna5.7"] = "Si avvicina a una macchina e ne estrae un liuto d'oro.",
	["cs.nocturna5.8"] = "Il liuto sfavilla di luce gialla tra le sue mani.",
	["cs.nocturna5.9"] = "Notturna alza la spada.",
	["cs.nocturna5.10"] = "Notturna le si lancia contro mentre dal liuto scaturiscono fulmini.",
	["cs.nocturna6.1"] = "Notturna sta sopra la macchina distrutta della Conduttrice, da cui sale del fumo, con la spada in mano.",
	["cs.nocturna6.2"] = "Si guarda la mano aperta.",
	["cs.nocturna6.3"] = "Un'energia rossa le turbina intorno. I suoi occhi brillano di rosso e lei ghigna, mostrando le zanne.",
	["cs.nocturna6.4"] = "Afferra un congegno d'oro che crepita di fulmini, lo solleva urlando e lo scaglia contro uno specchio.",
	["cs.nocturna6.5"] = "Afferra il liuto d'oro e lo solleva sopra la testa, con gli occhi fiammeggianti.",
	["cs.nocturna6.6"] = "I suoi occhi tornano normali. Esita.",
	["cs.nocturna6.7"] = "Nello specchio incrinato vede il suo io umano: una donna dalla pelle bruna, con i capelli castani ricci e occhiali rotondi.",
	["cs.nocturna6.8"] = "Abbassa il liuto e lo tiene con calma, gli occhi ora dorati.",
	["cs.nocturna6.9"] = "Dall'alto scende la luce lungo un pozzo. La sua sagoma vi sale dentro e scompare.",
	["cs.introDlc.1"] = "Notte in un cimitero sotto la luna piena e un cielo viola. Un ratto dagli occhi rosa luminosi striscia lungo un ramo.",
	["cs.introDlc.2"] = "Le foglie volano sopra le tombe.",
	["cs.introDlc.3"] = "Una mano scura e artigliata spunta dalla terra davanti a una tomba, mentre una sagoma dagli occhi rossi è appollaiata sopra.",
	["cs.introDlc.4"] = "Una figura incappucciata dagli occhi rossi luminosi incombe nel buio.",
	["cs.introDlc.5"] = "Primo piano: occhi rossi da vampiro e un sorriso furbo.",
	["cs.introDlc.6"] = "Una sagoma alata atterra accanto a una vecchia tomba di pietra.",
	["cs.introDlc.7"] = "Notturna sta sotto la luna piena, con le mani sui fianchi e le ali di pipistrello spiegate.",
	["cs.introDlc.8"] = "Pesta il piede e la lastra di pietra della tomba va in frantumi.",
	["cs.introDlc.9"] = "Scruta dentro la tomba rotta, dove un passaggio rosa luminoso scende verso il basso.",
	["cs.introDlc.10"] = "Si tuffa dentro, e mani di morti spuntano artigliando dalla terra dietro di lei.",
	["cs.aria0.1"] = "Nella cripta, Melody suona il liuto d'oro. Dietro di lei c'è sua madre Aria: capelli grigi, un vestito viola, un'armatura di cuoio marrone e un pugnale in mano.",
	["cs.aria0.2"] = "Primo piano: Melody la guarda con rabbia.",
	["cs.aria0.3"] = "Aria abbassa lo sguardo, piena di vergogna, illuminata dalla luce delle torce.",
	["cs.aria0.4"] = "La rabbia di Melody si addolcisce in tristezza; continua a suonare.",
	["cs.aria0.5"] = "Aria tende la mano aperta verso sua figlia.",
	["cs.aria1.1"] = "Aria suona il liuto d'oro davanti a un arco di pietra e teschi.",
	["cs.aria1.2"] = "In un santuario buio e invaso dalla vegetazione, solleva il liuto accanto a un piedistallo di pietra su cui arde una fiamma rosa.",
	["cs.aria1.3"] = "Il liuto prende vita tra le sue mani: il manico si arriccia come un drago d'oro e gli spuntano artigli, mentre la fiamma rosa divampa.",
	["cs.aria2.1"] = "Una taverna. Un giovane bardo con la barba rossa e una camicia blu suona il liuto su un piccolo palco, mentre i bevitori lo ignorano.",
	["cs.aria2.2"] = "Più tardi, in una foresta buia, lo stesso bardo, con uno zaino e un bastone da passeggio, si ripara gli occhi da un liuto d'oro che brilla su una pietra.",
	["cs.aria3.1"] = "Il bardo, Octavian, suona il liuto d'oro per un esercito di mostri: un enorme minotauro rosso con le corna d'oro, una melma verde piena di ossa, scheletri che agitano spade.",
	["cs.aria3.2"] = "Molto tempo prima, Aria attraversa la cripta vuota con una vanga e una torcia.",
	["cs.aria3.3"] = "Primo piano: Octavian, ora non morto e dalla pelle blu, con una lunga barba bianca e un mantello rosso, suona il liuto con occhi stanchi e vuoti.",
	["cs.aria3.4"] = "Il liuto gli scivola dalle mani e svanisce nell'oscurità.",
	["cs.aria4.1"] = "Aria, con una vanga al fianco, suona il liuto d'oro sopra una bara di pietra aperta in cui giace il NecroDancer.",
	["cs.aria4.2"] = "Mani blu afferrano il bordo della bara mentre lui si risveglia.",
	["cs.aria4.3"] = "Il NecroDancer si alza e allunga la mano verso il liuto, mentre Aria continua a suonare.",
	["cs.aria4.4"] = "In un'esplosione di luce viola, Aria gli porge il liuto e le sue mani blu lo afferrano.",
	["cs.aria4.5"] = "Lui strappa il liuto e scaraventa Aria da parte, con gli occhi rossi luminosi.",
	["cs.aria5.1"] = "Nel santuario invaso dalla vegetazione, Aria si ripara gli occhi mentre fulmini viola si riversano dal piedistallo intorno al liuto d'oro.",
	["cs.aria5.2"] = "Sbatte il liuto contro il piedistallo e ne scaturiscono fasci di luce viola.",
	["cs.aria5.3"] = "Fulmini viola la avvolgono e lei si accascia contro la pietra.",
	["cs.aria5.4"] = "Al tramonto, in cima a una collina, Cadence è davanti a una lapide con inciso il nome Aria.",
	["cs.aria5.5"] = "Melody e Dorian la raggiungono, a braccetto, mentre il sole tramonta.",
}
